agic","Shapechange","Spontaneous Wizard Spells","True Shapechange"],"domainPowers":{"airTurningUsesPerDay":19,"divinationCasterLevelBonus":1,"magicDomainUseItemsAsWizardLevel":20,"freedomOfMovementRoundsPerDay":19},"spellLikeAbilities":{"casterLevel":29,"divinationCasterLevel":30,"saveDc":"38 + spell level"},"spellcasting":{"wizardSpellsPerDayLevels0To17":"4/9/8/8/8/8/7/7/7/7/3/3/3/3/2/2/2/2","wizardBaseDc":"29 + spell level"},"possessions":{"gungnir":"+5 distance ghost touch holy keen returning wounding shortspear; range increment 80 ft.","draupnir":"Gold ring worth 1,000,000 gp that creates eight equal-value rings every ninth day.","hlidskjalf":"High Seat in Asgard; while seated Odin gains +30 insight on Scry checks and ignores distance and planar differences for divination spells."},"senses":{"normalRangeMiles":19,"sightRangeMiles":38},"portfolioSense":"All magic use and magic-item creation, discovery/recording/sharing of arcane knowledge, combat between groups, and events involving an Aesir; instantaneously and nineteen weeks into past and future.","automaticActions":{"skills":"any Knowledge skill, trained or untrained","freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any kind of magic item.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","companions":["Freke and Gere, legendary wolves","Hugin and Munin, legendary ravens","Sleipnir, legendary eight-legged horse"],"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"30/epic","fireResistance":24,"additionalOutsiderSkillPoints":true,"fighter":"No class-feature change in the official revision.","wizard":"Apply revised school-specialization rules if relevant.","defunctSkills":["Alchemy -> Craft (alchemy)","Innuendo ranks reassigned","Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival"]}}'),

